// offset для getUpdates храним в static data воркфлоу.
// Нет токена — выходим пустым списком: цепочка опроса не выполняется.
if (!$env.TELEGRAM_BOT_TOKEN) return [];
const sd = $getWorkflowStaticData('global');
return [{ json: { offset: Number(sd.tgOffset || 0) } }];

// Отдаём в основной флоу только новые текстовые сообщения.
// Транзитные ошибки Telegram (например, 409 при ручном getUpdates) пропускаем молча.
const res = $input.first().json;
if (res && res.ok === false) {
  if (res.error_code !== 409) throw new Error('getUpdates: ' + (res.description || 'ошибка Telegram API'));
  return [];
}
const updates = Array.isArray(res && res.result) ? res.result : [];
const sd = $getWorkflowStaticData('global');
let fresh = [];
if (updates.length) {
  const seen = Number(sd.tgOffset || 0);
  sd.tgOffset = Math.max(...updates.map(u => u.update_id)) + 1;
  // offset ещё не инициализирован и это самый первый опрос — считаем
  // накопившееся бэклогом и просто отмечаем прочитанным; всё, что придёт
  // позже (tgInit уже стоит), обрабатывается как новое.
  if (seen || sd.tgInit) {
    fresh = updates.filter(u => u.message && u.message.text && u.update_id >= seen);
  }
}
sd.tgInit = true;
return fresh.map(u => ({ json: u }));

// Сводим TG-update и webhook-запрос эмулятора к одному формату.
// system_prompt — копия backend/app/prompt.py (синхронизируйте вручную).
const SYSTEM_PROMPT = [
  'Ты — парсер заказов для сервиса записи клиентов. ',
  'Из свободного текста (с опечатками, эмодзи, без знаков препинания) извлеки структуру ',
  'и верни ТОЛЬКО валидный JSON без markdown-обёрток по схеме:',
  '{',
  '  "service_type": "короткое название услуги (нормализуй: например «стрижка собак», «ремонт ноутбуков»),',
  '  "fields": {произвольные ключи с деталями заказа: объект, дата, кличка, адрес, бюджет и т.п.},',
  '  "urgency": "low | normal | high | urgent",',
  '  "customer_name": "имя клиента или null",',
  '  "contact": "телефон/email/telegram из текста или null",',
  '  "valid": true | false',
  '}',
  'Правила:',
  '- valid=false, если невозможно понять, какая услуга нужна.',
  '- urgency=urgent только если в тексте есть явное «срочно», «!!» или жёсткий дедлайн.',
  '- Телефон нормализуй: только цифры и ведущий +.',
  '- Отвечай только JSON, без пояснений.',
].join('\n');

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const isTelegram = j.message !== undefined || j.update_id !== undefined;
  let text, chatId, name, source;
  if (isTelegram) {
    text = (j.message && j.message.text) || '';
    chatId = String((j.message && j.message.chat && j.message.chat.id) || '');
    name = (j.message && j.message.from && (j.message.from.first_name || j.message.from.username)) || 'Клиент';
    source = 'telegram';
  } else {
    const b = j.body || j;
    text = b.text || '';
    chatId = b.chat_id || 'emulator';
    name = b.name || 'Клиент';
    source = 'emulator';
  }
  out.push({ json: { text: String(text).trim(), chat_id: chatId, name, source, system_prompt: SYSTEM_PROMPT } });
}
if (!out.length || !out[0].json.text) {
  throw new Error('Пустое сообщение: текст заказа не найден');
}
return out;

// Достаём JSON из ответа LLM (терпим markdown-обёртки) и решаем, валиден ли заказ.
const raw = $input.first().json;
let content = '';
try { content = raw.choices[0].message.content || ''; } catch (e) {}

let attempts = 1;
try { if ($('Ретрай: пауза 3 сек').isExecuted) attempts = 2; } catch (e) {}

const norm = $('Нормализация ввода').first().json;

let parsed = null;
const match = String(content).match(/\{[\s\S]*\}/);
if (match) { try { parsed = JSON.parse(match[0]); } catch (e) {} }

const valid = Boolean(
  parsed &&
  parsed.valid !== false &&
  parsed.service_type &&
  String(parsed.service_type).trim().length >= 2
);

return [{ json: {
  ...norm,
  valid,
  attempts,
  parsed: parsed || {},
  error: parsed ? null : 'LLM вернул не-JSON или не распознал услугу',
} }];

// Формируем финальное сообщение клиенту из ответа backend.
const r = $input.first().json;
const norm = $('Нормализация ввода').first().json;

let reply;
let orderId = null;
let escalated = false;

if (r && r.confirmation_text && r.service_type === 'Ручная обработка') {
  reply = r.confirmation_text;
  orderId = r.id != null ? r.id : null;
  escalated = true;
} else if (r && r.confirmation_text) {
  reply = r.confirmation_text;
  orderId = r.id != null ? r.id : null;
} else {
  reply = 'Не удалось оформить заказ автоматически. Оператор подключится вручную и ответит в этом чате.';
  escalated = true;
}

const dbg = { input: String(JSON.stringify(r)).slice(0, 400) };
try { dbg.parsed = $('Разбор ответа LLM').first().json.parsed; } catch (e) { dbg.parsed = 'n/a'; }

return [{ json: {
  reply,
  order_id: orderId,
  ok: true,
  escalated,
  debug: dbg,
  source: norm.source,
  chat_id: norm.chat_id,
  name: norm.name,
} }];
